<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php'; require_once dirname(__DIR__).'/includes/csrf.php'; require_once __DIR__.'/layout.php'; require_once dirname(__DIR__).'/services/invoices.php';
$current=tuman_require_role('TEACHER'); $id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); if(!$id){http_response_code(404);exit('Invoice unavailable.');}$db=tuman_database();$invoice=tuman_teacher_invoice($db,$current['id'],(int)$id);if($invoice===null||$invoice['status']!=='DRAFT'){http_response_code(404);exit('Only a draft invoice can be discounted.');}$error=null;$discount=(string)$invoice['discount_amount'];
if($_SERVER['REQUEST_METHOD']==='POST'){$discount=trim((string)($_POST['discount_amount']??''));if(!tuman_csrf_is_valid($_POST['csrf_token']??null)){$error='Your request could not be verified. Please try again.';}else{try{tuman_set_invoice_discount($db,$current['id'],(int)$id,$discount);header('Location: /Tuman/teacher/invoice-view.php?id='.$id.'&discount=updated');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to update the discount right now.';}}}tuman_teacher_page_start('Apply discount');
?>
